import { requireVendorContext } from "@/lib/auth/vendor-context";
import { v1Data, v1Exception } from "@/lib/api/v1/response";
import { VendorEntitlementService } from "@/services/vendor-entitlement";
import { prisma } from "@/lib/prisma/client";
export async function GET() { try { const context = await requireVendorContext(); const [entitlement, subscriptionOrder, promotionalCreditAvailable] = await Promise.all([VendorEntitlementService.getForShop(context.vendorId), prisma.platformRevenueOrder.findFirst({ where: { vendorId: context.vendorId, type: "SUBSCRIPTION", status: { in: ["AWAITING_PAYMENT", "REVIEW_REQUIRED"] } }, select: { status: true }, orderBy: { updatedAt: "desc" } }), VendorEntitlementService.promotionalCreditAvailable(context.vendorId)]); return v1Data({ ...VendorEntitlementService.legacySummary(entitlement), entitlement, subscriptionPaymentState: subscriptionOrder?.status === "REVIEW_REQUIRED" ? "NEEDS_REVIEW" : subscriptionOrder ? "PENDING" : null, promotionalCreditAvailable }, 200, { "Cache-Control": "private, no-store" }); } catch (error) { return v1Exception(error); } }
